import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007L;

    static long sumModulo(long x, long y) {
        return (x + y) % MOD;
    }

    static long diffModulo(long x, long y) {
        x -= y;
        return (x < 0) ? x + MOD : x;
    }

    static long multModulo(long x, long y) {
        return (x * y) % MOD;
    }

    static long powModulo(long base, long exp) {
        long result = 1;
        long cur = base % MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = multModulo(result, cur);
            }
            cur = multModulo(cur, cur);
            exp >>= 1;
        }
        return result;
    }

    static long invModulo(long x) {
        return powModulo(x, MOD - 2);
    }

    static int nVar;
    static List<long[]> AVar;
    static long[][][] TVar;
    static Map<Long, Long> DPVar;
    static List<Integer>[] familyMaskListVar;
    static int[] familyCountVar;
    static int[] familyIdVar;

    static void setup() {
        familyMaskListVar = new ArrayList[nVar + 1];
        for (int i = 0; i <= nVar; i++) {
            familyMaskListVar[i] = new ArrayList<>();
        }
        familyCountVar = new int[1 << nVar];
        familyIdVar = new int[1 << nVar];

        for (int mask = 1; mask < (1 << nVar); ++mask) {
            familyCountVar[mask] = familyCountVar[mask >> 1] + (mask & 1);
        }
        for (int mask = 0; mask < (1 << nVar); ++mask) {
            int count = familyCountVar[mask];
            familyIdVar[mask] = familyMaskListVar[count].size();
            familyMaskListVar[count].add(mask);
        }

        for (int k = 0; k <= nVar; ++k) {
            int size = familyMaskListVar[k].size();
            for (int i = 0; i < size; ++i) {
                int cm = familyMaskListVar[k].get(i);
                for (int mask = 0; mask < (1 << nVar); ++mask) {
                    long ans = 0;
                    if ((mask & cm) == mask) continue;
                    for (int x = 0; x < nVar; ++x) {
                        if ((cm & (1 << x)) != 0) continue;
                        if ((mask & (1 << x)) == 0) continue;
                        int newmask = cm | (1 << x);
                        ans |= (1L << familyIdVar[newmask]);
                    }
                    TVar[k][i][mask] = ans;
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        nVar = Integer.parseInt(br.readLine());
        AVar = new ArrayList<>();
        for (int i = 0; i < nVar; i++) {
            String[] parts = br.readLine().split(" ");
            long[] row = new long[nVar];
            for (int j = 0; j < nVar; j++) {
                long val = Long.parseLong(parts[j]);
                row[j] = multModulo(val, invModulo(100));
            }
            AVar.add(row);
        }

        TVar = new long[nVar + 1][(1 << nVar)][1 << nVar];
        setup();

        DPVar = new HashMap<>();
        DPVar.put(1L, 1L);

        for (int k = 0; k < nVar; ++k) {
            Map<Long, Long> newDP = new HashMap<>();
            for (Map.Entry<Long, Long> entry : DPVar.entrySet()) {
                long mask = entry.getKey();
                long p = entry.getValue();
                long prob = 1;
                for (int i = 0; i < nVar; ++i) {
                    if (((mask & (1L << i)) != 0))
                        prob = multModulo(prob, AVar.get(k)[i]);
                    else
                        prob = multModulo(prob, diffModulo(1, AVar.get(k)[i]));
                }
                for (int edges = 0; edges < (1 << nVar); ++edges) {
                    long new_mask = 0;
                    long p2 = multModulo(prob, p);
                    int size = familyMaskListVar[k].size();
                    for (int i = 0; i < size; ++i) {
                        if (((mask & (1L << i)) != 0))
                            new_mask |= TVar[k][i][edges];
                    }
                    if (new_mask != 0) {
                        newDP.put(new_mask, sumModulo(newDP.getOrDefault(new_mask, 0L), p2));
                    }
                }
            }
            DPVar = newDP;
        }

        System.out.println(DPVar.getOrDefault(1L, 0L));
    }
}
